let selected_pnrs = transforms.selected_pnrs || [];
let pnr_index = transforms.pnr_index || 0;

let current_pnr = selected_pnrs[pnr_index];
ZT.setTransformData("current_pnr", current_pnr);

pnr_index += 1;
