let isMorePNR = true;
if (pnr_index >= selected_pnrs.length) {
    isMorePNR = false
    pnr_index = 0;
} 

ZT.setTransformData("isMorePNR", isMorePNR)
ZT.setTransformData("pnr_index", pnr_index);

