let selected_passengers = views.findorder || [];
let is_selected_passengers = selected_passengers[0]?.passengerFirstName != "" && selected_passengers[0]?.passengerId != null
ZT.setFormData("is_selected_passengers", is_selected_passengers);

if (is_selected_passengers) {
  const ALLOWED_KEYS = {
    passengerFirstName: "First Name",
    passengerLastName: "Last Name"
  };

  function formatPassengers(data) {
    return data
      .map(item =>
        Object.entries(ALLOWED_KEYS)
          .map(([key, label]) =>
            item[key]
              ? `<div><strong>${label}:</strong> ${item[key]}</div>`
              : ""
          )
          .join("")
      )
      .join('<hr style="margin: 8px 0;">');
  }

  let current_pnr = transforms.current_pnr;
  current_pnr = {
    ...current_pnr,
    passengers: selected_passengers,
    formatted_passengers: formatPassengers(selected_passengers)
  }
  ZT.setTransformData("current_pnr", current_pnr);

  let provider_booking_id = current_pnr.id.toString();
  let dynamic_provider_booking_id = `?providerBookingId=${provider_booking_id}`
  ZT.setFormData("dynamic_provider_booking_id", dynamic_provider_booking_id)
};

ZT.setViewData("findorder", [])

// Node 42 (GET Edvin Errands) fires next. Names the call so the failure screen router
// (node 94) and the retry router (node 88) know which request to blame and
// which Data node to re-fire.
ZT.setFormData("last_api_alias", "edvin__errand_configuration");
// Arms the log for the call about to fire. Its outcome is appended as a
// separate R entry where that outcome is known.
ZT.setFormData("api_trail", ZT.getVariableValue("api_trail", "") + "A~:~edvin__errand_configuration~:~" + ZT.getVariableValue("contact_reason", "") + "~||~A~:~get_edvin_prop_long_value~:~" + ZT.getVariableValue("contact_reason", "") + "~||~");

