// Renders as inline styles only, no <style> block, no <script>, no data-* attributes -
// a sanitizer strips markup after any of those and the table goes blank.
// class="zt-data" is required for Zingtree to capture the selection - it's not styling.
// Option values are action ids; dedupe by id, not name, since two actions can share a
// display name but carry different buckets.

let customer_action_pnrs = transforms.customer_action_pnrs || [];

const INK = "#101820";
const MUTED = "#667085";
const LINE = "#e7eaee";
const BG = "#f6f4ef";
const CARD = "#ffffff";
const BLUE = "#163a5f";
const SKY = "#d8ecf5";
const SAND = "#f3eadb";
const GREEN = "#dce8df";

const S = {
  board: "font-family:Arial,sans-serif;background:" + BG + ";border:1px solid " + LINE +
         ";border-radius:18px;padding:14px;",
  list: "display:flex;flex-wrap:wrap;gap:12px;",
  card: "flex:1 1 320px;min-width:0;box-sizing:border-box;background:" + CARD +
        ";border:1px solid " + LINE + ";border-radius:16px;padding:16px;",
  header: "display:flex;justify-content:space-between;gap:14px;align-items:flex-start;margin-bottom:12px;",
  title: "color:" + INK + ";font-size:16px;font-weight:700;letter-spacing:-0.01em;",
  pill: "display:inline-block;background:" + SKY + ";color:" + BLUE +
        ";border-radius:999px;padding:5px 10px;font-size:11px;font-weight:700;white-space:nowrap;",
  passengers: "color:" + INK + ";font-size:13px;line-height:1.45;margin-bottom:12px;",
  meta: "display:flex;flex-wrap:wrap;gap:8px;margin-bottom:12px;",
  metaItem: "background:" + SAND + ";border-radius:10px;padding:7px 9px;min-width:96px;",
  metaLabel: "display:block;color:" + MUTED + ";font-size:10px;font-weight:700;" +
             "text-transform:uppercase;letter-spacing:0.04em;margin-bottom:2px;",
  metaValue: "display:block;color:" + INK + ";font-size:12px;font-weight:600;",
  notes: "color:#344054;background:#fafafa;border:1px solid " + LINE +
         ";border-radius:12px;padding:10px 12px;font-size:13px;line-height:1.45;" +
         "white-space:pre-wrap;margin-bottom:12px;",
  actionRow: "display:block;",
  actionLabel: "display:block;color:" + MUTED + ";font-size:11px;font-weight:700;" +
               "text-transform:uppercase;letter-spacing:0.04em;margin-bottom:6px;",
  select: "width:100%;box-sizing:border-box;padding:11px 12px;font-size:14px;font-weight:600;color:" +
          INK + ";background:" + GREEN + ";border:1px solid #c8d8cd;border-radius:12px;cursor:pointer;",
  empty: "background:" + CARD + ";border:1px dashed " + LINE + ";border-radius:14px;" +
         "padding:22px;text-align:center;color:" + MUTED + ";font-size:14px;"
};

function escapeHtml(value) {
  return String(value)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function buildActionDropdown(item, rowIndex) {
  const uniqueActions = [];
  const seen = {};
  item.actions_array.forEach(action => {
    const id = String(action.actionId || action.id);
    if (seen[id]) return;
    seen[id] = true;
    uniqueActions.push({ id: id, name: action.name });
  });

  const variableName = "customer_action_" + item.pnr + "_" + rowIndex;
  const submitted = String(ZT.getVariableValue(variableName, "")).trim();
  const resolvedName = String(item.customer_action || "").trim();

  function isChosen(option) {
    if (submitted) return option.id === submitted || option.name === submitted;
    return resolvedName && option.name === resolvedName;
  }

  const anyChosen = uniqueActions.some(isChosen);

  // A stored selection that matches nothing on offer is stale (the agent went back
  // and changed the PNR's type after picking). Clear it so node 27 sees a clean
  // blank instead of failing to resolve a value that looks chosen but isn't.
  if (submitted && !anyChosen) {
    ZT.setFormData(variableName, "");
  }

  return `<select name="${escapeHtml(variableName)}" class="zt-data" style="${S.select}">` +
         `<option value=""${anyChosen ? "" : " selected"}>Select action</option>` +
         uniqueActions.map(a =>
           `<option value="${escapeHtml(a.id)}"${isChosen(a) ? " selected" : ""}>${escapeHtml(a.name)}</option>`
         ).join("") +
         `</select>`;
}

function buildMeta(label, value) {
  if (!value) return "";
  return `<div style="${S.metaItem}">` +
         `<span style="${S.metaLabel}">${escapeHtml(label)}</span>` +
         `<strong style="${S.metaValue}">${escapeHtml(value)}</strong>` +
         `</div>`;
}

function buildCustomerActionTable(pnrItems) {
  let html = `<div style="${S.board}"><div style="${S.list}">`;

  if (!pnrItems.length) {
    html += `<div style="${S.empty}">No customer action records found.</div>`;
  } else {
    pnrItems.forEach((item, index) => {
      html += `<div style="${S.card}">` +
                `<div style="${S.header}">` +
                  `<div style="${S.title}">${escapeHtml(item.pnr)}</div>` +
                  (item.category ? `<div style="${S.pill}">${escapeHtml(item.category)}</div>` : "") +
                `</div>` +
                `<div style="${S.passengers}">${item.formatted_passengers || ""}</div>` +
                `<div style="${S.meta}">` +
                  buildMeta("Channel", item.channel) +
                  buildMeta("Type", item.type) +
                `</div>` +
                (item.notes ? `<div style="${S.notes}">${escapeHtml(item.notes)}</div>` : "") +
                `<div style="${S.actionRow}">` +
                  `<div style="${S.actionLabel}">Customer action</div>` +
                  buildActionDropdown(item, index) +
                `</div>` +
              `</div>`;
    });
  }

  html += `</div></div>`;
  return html;
}

let customer_action_table_html = buildCustomerActionTable(customer_action_pnrs);

ZT.setTransformData("customer_action_table_html", customer_action_table_html);

19.content:
// END-OF-RUN API LOG. Reads the api_trail string this run has been accumulating
// and renders it: failures first, then everything that completed. Nothing routes
// on it - it is the read-out nodes 23 and 48 print.
//
// The trail is the record, not a set of pointers into `actions`. Two entry kinds,
// appended in call order, two delimiters so a parser needs two split() calls:
//     A~:~<alias>~:~<subject>              armed - a call is about to fire
//     R~:~<alias>~:~OK|FAIL~:~<code>~:~<detail>   result - written where it is known
// No timestamps: the script sandbox does not expose Date, and append order is the
// sequence anyway - the rows are numbered as they render.
// The script that consumes a response, and node 86 on the failure path, append the
// R entry at the moment the outcome is known, so a later call of the same alias
// cannot overwrite the evidence: four child-ticket creates leave four graded rows.
// Where no script consumes a response, the A entry has no R and this node grades
// it from `actions` as a fallback, and says so on the row.
// ===== API LOG RENDERER (keep IDENTICAL in nodes 19 and 86) =====
// The one duplicated block this tree allows, and only because the alternative is
// worse: the log has to render at the end of a SUCCESSFUL run (node 19 -> 23/48)
// and at an ABORTED one (node 86 -> the Request Failed screens -> 53), and those
// are two different paths with two different terminals. Routing both through one
// renderer needs a script-to-script hop and a router that cannot tell how it was
// entered.
// If this block changes, change it in BOTH nodes.
const trail = ZT.getVariableValue("api_trail", "");
const log_steps = JSON.parse(ZT.getVariableValue("api_steps", "{}"));

const rows = [];
trail.split("~||~").filter(entry => entry !== "").forEach(entry => {
  const f = entry.split("~:~");
  if (f[0] === "A") {
    rows.push({ seq: rows.length + 1, alias: f[1], subject: f[2] || "", status: "", code: "", detail: "" });
  } else {
    // Attach to the most recent still-open attempt of this alias.
    for (let i = rows.length - 1; i >= 0; i--) {
      if (rows[i].alias === f[1] && rows[i].status === "") {
        rows[i].status = f[2];
        rows[i].code = f[3] || "";
        rows[i].detail = f[4] || "";
        break;
      }
    }
  }
});

// Fallback for the calls no script reads back - the internal note, the ticket
// update and the errand registration. Graded from the response still in session,
// and flagged so the row is not mistaken for one recorded at the time.
rows.forEach(row => {
  row.step = log_steps[row.alias] || row.alias;
  if (row.status) return;
  const response = actions[row.alias];
  const meta = (response && response._zt_meta && response._zt_meta.response) ? response._zt_meta.response : {};
  const code = meta.code || meta.status || "";
  row.code = code;
  row.derived = true;
  row.status = !code ? "UNKNOWN" : (String(code).charAt(0) === "2" ? "OK" : "FAIL");
  row.detail = row.status === "FAIL" ? String(meta.message || meta.error || "").slice(0, 200) : "";
});

function escHtml(s) {
  return String(s === null || s === undefined ? "" : s)
    .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}

function rowHtml(row, accent) {
  return '<div style="padding:8px 10px;border-left:3px solid ' + accent + ';background:#ffffff;' +
    'border-radius:4px;margin:6px 0;font-size:13px;line-height:1.45;">' +
    '<div style="color:#111827;font-weight:600;"><span style="color:#9ca3af;font-weight:400;">' +
    row.seq + '. </span>' + escHtml(row.step) + '</div>' +
    '<div style="color:#6b7280;font-family:monospace;font-size:11px;word-break:break-all;">' +
    escHtml(row.alias) +
    (row.code ? ' - HTTP ' + escHtml(row.code) : ' - no response captured') +
    (row.derived ? ' - read back at end of run' : '') + '</div>' +
    (row.subject ? '<div style="color:#6b7280;font-size:12px;margin-top:2px;">' + escHtml(row.subject) + '</div>' : '') +
    (row.detail ? '<div style="color:#7f1d1d;margin-top:4px;">' + escHtml(row.detail) + '</div>' : '') +
    '</div>';
}

function card(title, tone, border, bg, items, accent, empty_text) {
  return '<div style="border:1px solid ' + border + ';background:' + bg +
    ';border-radius:10px;padding:12px 14px;margin:10px 0;">' +
    '<div style="font-weight:700;font-size:12px;color:' + tone +
    ';text-transform:uppercase;letter-spacing:0.03em;margin-bottom:6px;">' +
    escHtml(title) + ' (' + items.length + ')</div>' +
    (items.length
      ? items.map(row => rowHtml(row, accent)).join("")
      : '<div style="font-size:13px;color:#6b7280;font-style:italic;">' + escHtml(empty_text) + '</div>') +
    '</div>';
}

const failed = rows.filter(row => row.status === "FAIL");
const completed = rows.filter(row => row.status !== "FAIL");

// Transforms exception (HTML a content-node merge field renders): every other
// rendered block in this tree goes through transforms and this one matches them.
ZT.setTransformData("api_receipt_html", rows.length
  ? '<div style="font-family:Arial,Helvetica,sans-serif;max-width:560px;">' +
    '<div style="font-weight:700;font-size:12px;color:#374151;text-transform:uppercase;' +
    'letter-spacing:0.03em;">API requests this session (' + rows.length + ')</div>' +
    card("Failures", "#7f1d1d", "#fecaca", "#fef2f2", failed, "#dc2626", "None - every request came back 2xx.") +
    card("Completed", "#065f46", "#bbf7d0", "#f0fdf4", completed, "#16a34a", "Nothing recorded yet.") +
    '</div>'
  : ``);
// ===== END API LOG RENDERER =====

21.content:
// Builds the internal note posted to the Zendesk parent ticket by node 22.
// Every value is read straight from ZT.getVariableValue with its own default -
// no local wrapper, since getVariableValue already takes the fallback.
const genesys_conversation_id = ZT.getVariableValue("genesys_conversation_id", "N/A");
const genesys_interaction_type = ZT.getVariableValue("genesys_interaction_type", "N/A");
const contact_reason = ZT.getVariableValue("contact_reason", "N/A");
const language = ZT.getVariableValue("language", "N/A");
const zendesk_ticket_id = ZT.getVariableValue("zd_ticket_id", "N/A");
const order_reference = ZT.getVariableValue("order_reference", "N/A");

// Every PNR the agent actioned this run, with the action/type resolved by node 27.
const pnr_records = transforms.customer_action_pnrs || [];

const PNR_FIELDS = [
  { label: "Channel", key: "channel" },
  { label: "Category", key: "category" },
  { label: "Type", key: "type" },
  { label: "Customer Action", key: "customer_action" },
  { label: "Notes", key: "notes" },
  { label: "Description", key: "description" }
];

function formatPassengers(passengers) {
  return (passengers || [])
    .map(p => `First Name: ${p.passengerFirstName}, Last Name: ${p.passengerLastName}`)
    .join("\n");
}

let internal_note_details = "";

pnr_records.forEach(record => {
  let block = `**PNR**: ${record.pnr},
  **Contact Reason**: ${contact_reason},
  **Language**: ${language},
**Passengers**:
${formatPassengers(record.passengers)}
`;

  const lines = [];
  PNR_FIELDS.forEach(({ label, key }) => {
    if (record[key]) {
      lines.push(`**${label}**: ${record[key]}`);
    }
  });
  block += lines.join("\n");

  internal_note_details += block + "\n\n";
});

if (!pnr_records.length) {
  internal_note_details += "_No PNR actions were recorded for this session._\n\n";
}

internal_note_details += `
  **Order Reference**: ${order_reference},
  **Genesys Conversation ID**: ${genesys_conversation_id},
  **Genesys Interaction Type**: ${genesys_interaction_type},
  **Ticket ID**: ${zendesk_ticket_id}
`;

internal_note_details += `
  **Child Ticket Summary**:

  ${transforms.child_tickets_note || ""}
  `;

// The Add Internal Note Connected Object (create_internal_note__no_group_id)
// drops this note into a hand-authored JSON body, so it is escaped here and the
// outer quotes JSON.stringify adds are sliced back off.
//
// The same single-object-then-stringify shape node 44 uses for its Edvin payload
// would fit here too, but this CO's request body lives in the admin UI and is not
// visible in this export. Confirm its field names there before changing this.
let stringified_note_details = JSON.stringify(internal_note_details).slice(1, -1);
ZT.setTransformData("internal_note_details", stringified_note_details);

// No tag write here by design - Zendesk tagging runs off the ::tag_name suffix on
// button text, not a tag API call from a script.

// Node 22 (Zendesk - Add Internal Note) fires next. Names the call so the failure screen router
// (node 94) and the retry router (node 88) know which request to blame and
// which Data node to re-fire.
ZT.setFormData("last_api_alias", "create_internal_note__no_group_id");
// Arms the log for the call about to fire. Its outcome is appended as a
// separate R entry where that outcome is known.
ZT.setFormData("api_trail", ZT.getVariableValue("api_trail", "") + "A~:~create_internal_note__no_group_id~:~Ticket " + ZT.getVariableValue("zd_ticket_id", "") + "~||~");

