27.content:
// Stitches the agent's customer-action picks back off node 25's table, resolves
// each to a real action + bucket, then builds the ONE structure everything
// downstream walks:
//
//   transforms.work_queue = [
//     { ticket: { ..., grand_child_tickets: [ { ... }, ... ] },
//       errands: [ { ...Edvin errand record... } ] },
//     ...
//   ]
//
// One entry per Zendesk ticket this run will create, with its grand children
// nested inside it and the Edvin errand(s) that ticket covers sitting beside it.
// Node 32 walks the whole thing with a single loop (see claude.md "UNIFIED
// TICKET LOOP"). transforms.final_pnrs is unchanged and still built first, in
// its original order, so node 44 keeps working exactly as before - the errands
// arrays hold references to those same records, not copies.

let customer_action_pnrs = transforms.customer_action_pnrs || [];

function findAction(item, selectedValue) {
  const wanted = String(selectedValue);
  return item.actions_array.find(a =>
    String(a.actionId) === wanted || String(a.id) === wanted || String(a.name) === wanted
  );
}

let unresolved_selections = [];
let resolved_pnrs = [];

customer_action_pnrs.forEach((item, index) => {
  const variableName = "customer_action_" + item.pnr + "_" + index;
  const rawSelection = ZT.getVariableValue(variableName, "");
  const selectedAction = findAction(item, rawSelection);

  if (!selectedAction || !selectedAction.bucket) {
    unresolved_selections.push({ pnr: item.pnr, type: item.type });
    return;
  }

  resolved_pnrs.push({
    ...item,
    customer_action: selectedAction.name,
    actionId: selectedAction.actionId,
    bucket: selectedAction.bucket,
    bucketId: selectedAction.bucketId,
    edvin_actions: selectedAction.edvin_actions
  });
});

function buildUnresolvedHtml(rows) {
  let html = '<div style="font-family:Arial,sans-serif;background:#fff7ed;border:1px solid #fed7aa;border-radius:14px;padding:16px 18px;">';
  html += '<h3 style="margin:0 0 6px;font-size:16px;color:#7c2d12;">The customer action did not come through</h3>';
  html += '<p style="margin:0 0 12px;font-size:14px;line-height:1.5;color:#7c2d12;">Nothing has been recorded for this order yet - no tickets, no errand in Edvin. Pick the action again for the PNR(s) below and continue.</p>';
  html += '<ul style="margin:0;padding-left:18px;">';
  rows.forEach(row => {
    html += '<li style="font-size:14px;line-height:1.6;color:#7c2d12;"><span style="font-weight:700;">' + row.pnr + '</span> (' + row.type + ')</li>';
  });
  html += '</ul></div>';
  return html;
}

const errandKey = item => item.type + "|" + item.customer_action;
const isProceed = item => item.bucket.toLowerCase() === "proceed";
const joinPnrs = items => [...new Set(items.map(i => i.pnr))].join(", ");

function mergePassengers(items) {
  const unique = [];
  const seen = new Set();
  items.forEach(item => {
    (item.passengers || []).forEach(p => {
      const key = (p.passengerFirstName || "") + "|" + (p.passengerLastName || "");
      if (!seen.has(key)) {
        seen.add(key);
        unique.push(p);
      }
    });
  });
  return unique;
}

// Same shape as mergePassengers/joinPnrs: one errand can carry N PNRs, so its
// agent notes have to carry all N too. PNR-prefixed so Edvin/the agent can tell
// whose note is whose; de-duped so two PNRs with identical text (or both blank)
// don't repeat. See buildFinalErrandRecord below - this is the same "notes"
// field buildFinalErrandRecord below carries across the whole group.
function mergeNotes(items) {
  const seen = new Set();
  const parts = [];
  items.forEach(item => {
    const note = (item.notes || "").trim();
    if (note && !seen.has(note)) {
      seen.add(note);
      parts.push(item.pnr + ": " + note);
    }
  });
  return parts.join(" | ");
}

function groupByErrand(items) {
  const map = new Map();
  items.forEach(item => {
    const key = errandKey(item);
    if (!map.has(key)) map.set(key, []);
    map.get(key).push(item);
  });
  return [...map.values()];
}

// ERRAND RECORD. When 2+ PNRs share the same (type + customer_action) pair they
// collapse into ONE Edvin errand, so the record has to be built from the whole
// group, never from group[0] alone - an errand covering N PNRs carries all N, the
// same way the ticket built below does.
function buildFinalErrandRecord(group) {
  const orderReferences = [...new Set(group.map(item => item.orderReference).filter(Boolean))];
  return {
    ...group[0],
    pnr: joinPnrs(group),
    passengers: mergePassengers(group),
    formatted_passengers: [...new Set(group.map(item => item.formatted_passengers))].join(""),
    orderReference: orderReferences.join(", ") || group[0].orderReference,
    providerBookingIds: JSON.stringify(group.map(item => item.id).filter(id => id != null)),
    notes: mergeNotes(group)
  };
}

// --- the work queue ---------------------------------------------------------
// Ticket shape is deliberately flat and self-describing: node 32 reads a ticket
// without needing to know whether it is a parent or a grand child.
//   kind        child | silent | grand_child   (display + status only)
//   status      open | solved  - what node 65 sends to the Zendesk update call
//   errand_key  type|customer_action - the join key to final_pnrs / node 44

function buildTicket(kind, titlePrefix, group, grandChildren) {
  // Unconfirmed Booking and Orphan paths: joinPnrs(group)
  // is "" when there is no real PNR. Fall back to the no_pnr_label the bridge
  // node (93) set on the synthetic record, so the ticket title reads
  // "Child Ticket: Orphan Errand" instead of "Child Ticket: " with nothing
  // after the colon. Only affects display/title - buildFinalErrandRecord's
  // pnr (the actual Edvin errand record) is untouched by this.
  const displayPnr = joinPnrs(group) || group[0].no_pnr_label || "";
  return {
    kind: kind,
    title: titlePrefix + ": " + displayPnr,
    pnr: displayPnr,
    bucket: group[0].bucket,
    category: group[0].category,
    contact_reason: group[0].category,
    customer_action: group[0].customer_action,
    type: group[0].type,
    channel: group[0].channel,
    genesys_interaction_type: group[0].genesys_interaction_type,
    errand_key: errandKey(group[0]),
    status: kind === "silent" ? "solved" : "open",
    passengers: mergePassengers(group),
    grand_child_tickets: grandChildren || []
  };
}

function buildWorkQueue(pnrs, errandRecords) {
  const errandByKey = new Map(errandRecords.map(record => [errandKey(record), record]));
  const queue = [];

  function enqueue(ticket) {
    const keys = [ticket.errand_key].concat(ticket.grand_child_tickets.map(gc => gc.errand_key));
    const errands = [...new Set(keys)].map(key => errandByKey.get(key)).filter(Boolean);
    queue.push({ ticket: ticket, errands: errands });
  }

  const proceed = pnrs.filter(isProceed);
  const nonProceed = pnrs.filter(item => !isProceed(item));

  // Silent tickets first, the proceed child ticket last - the order the old
  // buildChildTickets() sort produced, kept so nothing downstream shifts.
  groupByErrand(nonProceed).forEach(group => enqueue(buildTicket("silent", "Silent Ticket", group, [])));

  if (proceed.length) {
    const combos = groupByErrand(proceed);
    // Grand children only exist when the proceed PNRs span 2+ distinct
    // (type + customer_action) pairs - one pair is just the child ticket.
    const grandChildren = combos.length > 1
      ? combos.map(group => buildTicket("grand_child", "Grandchild Ticket", group, []))
      : [];
    enqueue(buildTicket("child", "Child Ticket", proceed, grandChildren));
  }

  return queue;
}

function buildTicketsNote(queue) {
  const childCount = queue.filter(entry => entry.ticket.kind === "child").length;
  const silentCount = queue.filter(entry => entry.ticket.kind === "silent").length;
  const grandchildCount = queue.reduce((sum, entry) => sum + entry.ticket.grand_child_tickets.length, 0);

  let note = "(Child Tickets: " + childCount + ", Grand Child Tickets: " + grandchildCount +
    ", Silent Tickets: " + silentCount + ")\n\n";

  queue.forEach(entry => {
    const t = entry.ticket;
    const label = t.kind === "silent" ? "Silent Ticket" : "Child Ticket";

    note += "**" + label + "**: " + t.pnr + ",\n  **Contact Reason**: " + t.category +
      ",\n  **Type**: " + t.type + ",\n  **Customer Action**: " + t.customer_action + "\n";

    t.grand_child_tickets.forEach(gc => {
      note += "  - **Grandchild Ticket**: " + gc.pnr + ", Action: " + gc.customer_action +
        ", Contact Reason: " + gc.contact_reason +
        ", Genesys Interaction Type: " + gc.genesys_interaction_type + "\n";
    });

    note += "\n";
  });

  return note.trim();
}

let final_pnrs = groupByErrand(resolved_pnrs).map(buildFinalErrandRecord);
let work_queue = buildWorkQueue(resolved_pnrs, final_pnrs);

let planned_ticket_titles = [];
work_queue.forEach(entry => {
  planned_ticket_titles.push(entry.ticket.title);
  entry.ticket.grand_child_tickets.forEach(gc => planned_ticket_titles.push(gc.title));
});

ZT.setTransformData("customer_action_pnrs", resolved_pnrs);
ZT.setFormData("has_unresolved_selections", unresolved_selections.length > 0);
ZT.setFormData("unresolved_selections_count", unresolved_selections.length);
ZT.setTransformData("unresolved_selections", unresolved_selections);
ZT.setTransformData("unresolved_note_html", buildUnresolvedHtml(unresolved_selections));
ZT.setTransformData("work_queue", work_queue);
ZT.setTransformData("planned_ticket_titles", planned_ticket_titles);
ZT.setTransformData("final_pnrs", final_pnrs);
ZT.setTransformData("child_tickets_note", buildTicketsNote(work_queue));

// The loop cursors start fresh every time this node runs: node 25 has Back
// enabled, so a re-entry has to re-walk the queue from the top.
ZT.setFormData("queue_index", 0);
ZT.setFormData("grandchild_index", -1);

29.content:
// Mid-ticket restart for Additional / Different Request (node 47 -> here -> node
// 77). Re-enters the flow without passing through the root, so anything the root
// resets and this node does not will leak into the second pass.
//
// Resets loop and reconciliation state ONLY. Two things it deliberately leaves
// alone: the inbound Zendesk intake values (order reference, language, Genesys
// ids), and `contact_reason`, which node 47's select has just rewritten through
// its score_var. Node 95 writes the agent's pick back to Zendesk on the way past.

// --- Intake-loop state ---------------------------------------------------------
ZT.setTransformData("customer_action_pnrs", []);
ZT.setTransformData("final_pnrs", []);
// final_pnrs_count is the dangerous one: node 44 uses it as its cursor, so a stale
// value makes the second pass start mid-array and skip Edvin registrations.
ZT.setTransformData("final_pnrs_count", 0);
ZT.setTransformData("selected_pnrs", []);
ZT.setTransformData("current_pnr", {});
ZT.setTransformData("pnr_index", 0);
ZT.setTransformData("isMorePNR", false);
ZT.setTransformData("pnr_banner", ``);
ZT.setTransformData("actions_array", []);
ZT.setTransformData("customer_action_table_html", ``);
ZT.setTransformData("internal_note_details", ``);
ZT.setTransformData("child_tickets_note", ``);
