65.content:
// Resolves the side conversation's BACKING Zendesk ticket id and files it under
// both keys the rest of the tree needs it by:
//   ticket_ids_by_errand_key[errand_key]      -> node 44's registerErrand payload
//   resolved_ticket_ids_by_queue_index[qi]    -> node 32's grand children
// Runs for parent and grand child tickets alike.

const current_ticket = transforms.current_ticket || {};

// This ticket's details lookup. Recorded per pass, same reason as the create.
ZT.setFormData("api_trail", ZT.getVariableValue("api_trail", "") + "R~:~get_side_conversation_detail~:~" + (String(actions.get_side_conversation_detail._zt_meta.response.code).charAt(0) === "2" ? "OK" : "FAIL") + "~:~" + actions.get_side_conversation_detail._zt_meta.response.code + "~||~");

const side_conversation_ticket_id = actions.get_side_conversation_detail.side_conversations
  .find(x => x.id == ZT.getVariableValue("side_conversation_id", ""))
  .external_ids.targetTicketId;
ZT.setFormData("side_conversation_ticket_id", side_conversation_ticket_id);

// Silent tickets are created and immediately solved; everything else stays open.
// The status is decided in node 27 and carried on the ticket, not re-derived
// from the title here.
ZT.setFormData("ticket_status", current_ticket.status || "open");

const ticket_ids_by_errand_key = transforms.ticket_ids_by_errand_key || {};
ticket_ids_by_errand_key[current_ticket.errand_key] = side_conversation_ticket_id;
ZT.setTransformData("ticket_ids_by_errand_key", ticket_ids_by_errand_key);

// Only a parent ticket can be a grand child's target. current_is_grand_child is
// the position node 32 just processed, not the cursor - the cursor has moved on.
if (String(ZT.getVariableValue("current_is_grand_child", "false")) !== "true") {
  const resolved_ticket_ids_by_queue_index = transforms.resolved_ticket_ids_by_queue_index || {};
  resolved_ticket_ids_by_queue_index[ZT.getVariableValue("current_queue_index", 0)] = side_conversation_ticket_id;
  ZT.setTransformData("resolved_ticket_ids_by_queue_index", resolved_ticket_ids_by_queue_index);
}

// Node 66 (Update Child Ticket) fires next. Names the call so the failure screen router
// (node 94) and the retry router (node 88) know which request to blame and
// which Data node to re-fire.
ZT.setFormData("last_api_alias", "zingtree_redesign__update_side_conversation");
// Arms the log for the call about to fire. Its outcome is appended as a
// separate R entry where that outcome is known.
ZT.setFormData("api_trail", ZT.getVariableValue("api_trail", "") + "A~:~zingtree_redesign__update_side_conversation~:~" + ZT.getVariableValue("side_conversation_id", "") + "~||~");

86.content:
// Shared failure handler. Every API status-check node routes its failure branch
// here. It grades the call that just failed and renders one card; node 94 then
// picks the failure screen and node 88 the retry target, both keyed off
// last_api_alias, which the script before each Data node sets.
const failed_alias = ZT.getVariableValue("last_api_alias", "");

// Readable name for the request, so the card says "Edvin - Register Errand"
// rather than an alias. The catalogue is seeded by the root and shared with the
// end-of-run receipt; only the create call refines its label, from ticket_kind.
const api_steps = JSON.parse(ZT.getVariableValue("api_steps", "{}"));
const failed_step = (failed_alias === "create_child_ticket"
  ? "ZD - Create " + ZT.getVariableValue("ticket_kind", "Child Ticket")
  : api_steps[failed_alias]) || failed_alias;


// What the run was working on when it failed, so the agent can tell one PNR or
// ticket apart from another in a long session.
const failed_ref = (transforms.current_ticket || {}).title ||
  ZT.getVariableValue("order_reference", "");

const response = actions[failed_alias] || null;
const meta = (response && response._zt_meta && response._zt_meta.response) ? response._zt_meta.response : {};

function escHtml(s) {
  return String(s === null || s === undefined ? "" : s)
    .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}

const failure_html =
  '<div style="font-family:Arial,Helvetica,sans-serif;max-width:560px;border:1px solid #fecaca;' +
  'background:#fef2f2;border-radius:10px;padding:14px 16px;">' +
  '<div style="font-size:15px;font-weight:700;color:#7f1d1d;margin-bottom:4px;">Request failed</div>' +
  '<div style="font-size:13px;color:#7f1d1d;line-height:1.5;">The <strong>' +
  escHtml(failed_step) + '</strong> request did not come back with a 200 or 201' +
  (meta.code ? ' (received HTTP ' + escHtml(meta.code) + ')' : '') + '.</div>' +
  (failed_ref ? '<div style="font-size:12px;color:#991b1b;margin-top:6px;">Working on: ' + escHtml(failed_ref) + '</div>' : '') +
  '<div style="font-size:13px;color:#7f1d1d;margin-top:8px;">Nothing further has been written for this step. ' +
  'You can retry the same request, or end the session.</div>' +
  '<div style="margin-top:10px;font-size:11px;font-family:monospace;color:#7f1d1d;' +
  'background:#ffffff;border:1px solid #fecaca;border-radius:6px;padding:8px;' +
  'max-height:180px;overflow:auto;white-space:pre-wrap;">' +
  escHtml(response ? JSON.stringify(response, null, 2).slice(0, 2000) : "No response body was captured.") +
  '</div></div>';

// The failed call goes into the log as a graded entry. Node 86 is the only place
// a failure is known for the calls no success-path script reads back.
ZT.setFormData("api_trail", ZT.getVariableValue("api_trail", "") + "R~:~" + failed_alias + "~:~FAIL~:~" + (meta.code || "") + "~:~" + String(meta.message || meta.error || "").replace(/[~|]/g, "-").slice(0, 200) + "~||~");

ZT.setTransformData("failure_html", failure_html);

// ===== API LOG RENDERER (keep IDENTICAL in nodes 19 and 86) =====
// The one duplicated block this tree allows, and only because the alternative is
// worse: the log has to render at the end of a SUCCESSFUL run (node 19 -> 23/48)
// and at an ABORTED one (node 86 -> the Request Failed screens -> 53), and those
// are two different paths with two different terminals. Routing both through one
// renderer needs a script-to-script hop and a router that cannot tell how it was
// entered.
// If this block changes, change it in BOTH nodes.
const trail = ZT.getVariableValue("api_trail", "");
const log_steps = JSON.parse(ZT.getVariableValue("api_steps", "{}"));

const rows = [];
trail.split("~||~").filter(entry => entry !== "").forEach(entry => {
  const f = entry.split("~:~");
  if (f[0] === "A") {
    rows.push({ seq: rows.length + 1, alias: f[1], subject: f[2] || "", status: "", code: "", detail: "" });
  } else {
    // Attach to the most recent still-open attempt of this alias.
    for (let i = rows.length - 1; i >= 0; i--) {
      if (rows[i].alias === f[1] && rows[i].status === "") {
        rows[i].status = f[2];
        rows[i].code = f[3] || "";
        rows[i].detail = f[4] || "";
        break;
      }
    }
  }
});

// Fallback for the calls no script reads back - the internal note, the ticket
// update and the errand registration. Graded from the response still in session,
// and flagged so the row is not mistaken for one recorded at the time.
rows.forEach(row => {
  row.step = log_steps[row.alias] || row.alias;
  if (row.status) return;
  const response = actions[row.alias];
  const meta = (response && response._zt_meta && response._zt_meta.response) ? response._zt_meta.response : {};
  const code = meta.code || meta.status || "";
  row.code = code;
  row.derived = true;
  row.status = !code ? "UNKNOWN" : (String(code).charAt(0) === "2" ? "OK" : "FAIL");
  row.detail = row.status === "FAIL" ? String(meta.message || meta.error || "").slice(0, 200) : "";
});

function escHtml(s) {
  return String(s === null || s === undefined ? "" : s)
    .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}

function rowHtml(row, accent) {
  return '<div style="padding:8px 10px;border-left:3px solid ' + accent + ';background:#ffffff;' +
    'border-radius:4px;margin:6px 0;font-size:13px;line-height:1.45;">' +
    '<div style="color:#111827;font-weight:600;"><span style="color:#9ca3af;font-weight:400;">' +
    row.seq + '. </span>' + escHtml(row.step) + '</div>' +
    '<div style="color:#6b7280;font-family:monospace;font-size:11px;word-break:break-all;">' +
    escHtml(row.alias) +
    (row.code ? ' - HTTP ' + escHtml(row.code) : ' - no response captured') +
    (row.derived ? ' - read back at end of run' : '') + '</div>' +
    (row.subject ? '<div style="color:#6b7280;font-size:12px;margin-top:2px;">' + escHtml(row.subject) + '</div>' : '') +
    (row.detail ? '<div style="color:#7f1d1d;margin-top:4px;">' + escHtml(row.detail) + '</div>' : '') +
    '</div>';
}

function card(title, tone, border, bg, items, accent, empty_text) {
  return '<div style="border:1px solid ' + border + ';background:' + bg +
    ';border-radius:10px;padding:12px 14px;margin:10px 0;">' +
    '<div style="font-weight:700;font-size:12px;color:' + tone +
    ';text-transform:uppercase;letter-spacing:0.03em;margin-bottom:6px;">' +
    escHtml(title) + ' (' + items.length + ')</div>' +
    (items.length
      ? items.map(row => rowHtml(row, accent)).join("")
      : '<div style="font-size:13px;color:#6b7280;font-style:italic;">' + escHtml(empty_text) + '</div>') +
    '</div>';
}

const failed = rows.filter(row => row.status === "FAIL");
const completed = rows.filter(row => row.status !== "FAIL");

// Transforms exception (HTML a content-node merge field renders): every other
// rendered block in this tree goes through transforms and this one matches them.
ZT.setTransformData("api_receipt_html", rows.length
  ? '<div style="font-family:Arial,Helvetica,sans-serif;max-width:560px;">' +
    '<div style="font-weight:700;font-size:12px;color:#374151;text-transform:uppercase;' +
    'letter-spacing:0.03em;">API requests this session (' + rows.length + ')</div>' +
    card("Failures", "#7f1d1d", "#fecaca", "#fef2f2", failed, "#dc2626", "None - every request came back 2xx.") +
    card("Completed", "#065f46", "#bbf7d0", "#f0fdf4", completed, "#16a34a", "Nothing recorded yet.") +
    '</div>'
  : ``);
// ===== END API LOG RENDERER =====

90.content:
// Classify this order right after Edvin - Find Order returns: Christina's
// "Unconfirmed Booking" case (Subflow 1, build guide section 2) is an order
// that exists but never got a PNR - Zendesk has an order reference, Edvin's
// Find Order ran fine, but there is nothing to select on node 6.
// Trigger condition per Christina (9/1 call): a dedicated contact reason /
// "contact region" value, PLUS a cross-check against zero PNRs coming back -
// treat either one as enough, since a mis-set contact reason should not trap
// an agent who genuinely has no PNR to pick, and vice versa.
//
// TODO(confirm before go-live, build guide open question #1): Christina
// described this as a dedicated "contact region" on her own Zendesk screen.
// This tree only has a contact REASON field/value - node 10's
// contact_reasons_dynamic list already carries the exact value below
// ({ label: "Contact Reason Unconfirmed Booking", value:
// "contact_reason__unconfirmed_booking" }), which is the strongest evidence
// available that they are the same selector. Confirm with Christina that
// "contact region" and this contact-reason value are the same thing before
// relying on this branch alone in production.
const CONTACT_REASON_UNCONFIRMED_BOOKING = "contact_reason__unconfirmed_booking";

// Node 4's outcome, recorded now rather than read back later: nothing else in
// the run overwrites actions.findorder, but the log is the record either way.
ZT.setFormData("api_trail", ZT.getVariableValue("api_trail", "") + "R~:~findorder~:~" + (String(actions.findorder._zt_meta.response.code).charAt(0) === "2" ? "OK" : "FAIL") + "~:~" + actions.findorder._zt_meta.response.code + "~||~");

const contactReason = ZT.getVariableValue("contact_reason", "");
const bookingDetails = (actions.findorder && actions.findorder.orderProviderBookingDetails) || [];
const linkedRefs = (actions.findorder && actions.findorder.orderLinkedProviderReferences) || [];
const hasNoPnrs = (bookingDetails.length + linkedRefs.length) === 0;

const isUnconfirmedBooking = contactReason === CONTACT_REASON_UNCONFIRMED_BOOKING || hasNoPnrs;

ZT.setFormData("is_unconfirmed_booking", isUnconfirmedBooking);
ZT.setFormData("errand_path_kind", isUnconfirmedBooking ? "unconfirmed_booking" : "normal");

93.content:
// Shared bridge for the two PNR-less paths: Unconfirmed Booking (node 101) and
// Orphan Errand (node 77's "No Order Reference" button). Both skip the PNR
// selection screens (6/54/55/7/8/9/56/57) entirely, so this node's only job is to
// hand node 2 the same record shape node 7 would build for a real PNR.
//
// Orphan-ness is DERIVED here from the actual condition - no order reference
// resolved - rather than being set by an upstream node that has to remember to do
// it. That removes the failure mode where the classification silently falls back
// to "normal" and the errand registers against a blank order reference.
const order_reference = ZT.getVariableValue("order_reference", "");
const genesys_interaction_type = ZT.getVariableValue("genesys_interaction_type", "");

const isOrphan = ZT.getVariableValue("errand_path_kind", "") === "orphan" || !order_reference;
ZT.setFormData("errand_path_kind", isOrphan ? "orphan" : "unconfirmed_booking");

let resolved_order_reference;
if (isOrphan) {
  // Elis (Edvin): send the order reference as -999 and it is treated the same way
  // as an orphan on their side.
  resolved_order_reference = "-999";
} else {
  // Unconfirmed Booking: a REAL order reference. Only the PNR is optional on this
  // path - the order reference stays required.
  resolved_order_reference = order_reference ||
    (actions.findorder && actions.findorder.orderReference) || "";
}

// zendeskChannelIdentifier normally comes from node 61, which neither path passes
// through (Orphan skips nodes 4 and 61 entirely; Unconfirmed Booking skips 61's
// PNR-mapping half but still needs the channel).
function mapGenesysInteractionType(value) {
  const interactionTypeMap = {
    "genesys_interaction_type__call": "Phone",
    "genesys_interaction_type__message": "Chat",
    "genesys_interaction_type__email": "Email"
  };
  return `Zingtree.Channels.${interactionTypeMap[value]}`;
}
const contactType = genesys_interaction_type || "genesys_interaction_type__call";
ZT.setFormData("zendeskChannelIdentifier", mapGenesysInteractionType(contactType));

// no_pnr_label feeds node 27's buildTicket fallback so the ticket title reads
// "Child Ticket: Orphan Errand" / "Child Ticket: Unconfirmed Booking - <order
// ref>" instead of stopping blank after the colon.
const noPnrLabel = isOrphan ? "Orphan Errand" : ("Unconfirmed Booking - " + resolved_order_reference);

// Same shape node 7 hands node 2 via transforms.current_pnr for a real PNR - node
// 2 merges in channel/category/type/notes/actions_array identically either way.
// pnr stays "" ON PURPOSE: Edvin has not confirmed that registerErrand accepts a
// null PNR, so leave it blank rather than guessing a placeholder into the field
// Edvin stores against the order.
const current_pnr = {
  pnr: "",
  no_pnr_label: noPnrLabel,
  orderReference: resolved_order_reference,
  orderId: (actions.findorder && actions.findorder.orderId) || "",
  passengers: [],
  formatted_passengers: "",
  id: null
};

ZT.setTransformData("current_pnr", current_pnr);
ZT.setFormData("isMorePNR", false);
ZT.setFormData("pnr_index", 0);

// The resolved reference is session state only. The orphan sentinel (-999) is
// deliberately NOT written back to the Zendesk order-reference field - it is a
// value Edvin understands, not something to stamp on the ticket.
ZT.setFormData("order_reference", resolved_order_reference);
ZT.setFormData("orderReference", resolved_order_reference);

// Node 42 (GET Edvin Errands) fires next on this path.
ZT.setFormData("last_api_alias", "edvin__errand_configuration");
// Arms the log for the call about to fire. Its outcome is appended as a
// separate R entry where that outcome is known.
ZT.setFormData("api_trail", ZT.getVariableValue("api_trail", "") + "A~:~edvin__errand_configuration~:~" + resolved_order_reference + "~||~A~:~get_edvin_prop_long_value~:~" + resolved_order_reference + "~||~");
ZT.setFormData("dynamic_provider_booking_id", "")

95.content:
// Order reference gate, and the write-back point for everything the agent can
// change on node 77.
//
// Node 77 renders "Order Reference*" as a merge field rather than an input, so
// the asterisk is not enforced by the form. This node is the enforcement: a blank
// reference is routed by node 96 to node 97 ("add it to the ticket and try
// again") instead of reaching Edvin Find Order and coming back as an API failure
// screen, which would read like an outage rather than a missing field.
//
// DELIBERATE custom_field_ USE. The house rule is that only the root reads a raw
// Zendesk field id; this node WRITES two of them, which is the other half of the
// pair. It has to happen after node 77 - that is the screen the agent changes
// them on. Node 10 and predefined_vars are the only other places an id appears.
const order_reference = String(ZT.getVariableValue("order_reference", "")).trim();
const contact_reason = String(ZT.getVariableValue("contact_reason", "")).trim();

ZT.setFormData("order_reference", order_reference);
ZT.setFormData("orderReference", order_reference); // Connected Object bodies read this name
ZT.setFormData("has_order_reference", order_reference !== "");

// Write the agent-facing values back to THIS org's Zendesk ticket fields, so the
// ticket and the tree agree from here on. Env-specific ids - the only other place
// they appear is node 10's intake block and predefined_vars.
// Blank is never written back: it would clear a value the ticket already holds.
if (order_reference) {
  ZT.setFormData("custom_field_33772689958162", order_reference);
}
if (contact_reason) {
  ZT.setFormData("custom_field_29559177650834", contact_reason);
}

// Node 4 (Edvin - Find Order) fires next once node 96 passes this gate.
ZT.setFormData("last_api_alias", "findorder");
// Arms the log for the call about to fire. Its outcome is appended as a
// separate R entry where that outcome is known.
ZT.setFormData("api_trail", ZT.getVariableValue("api_trail", "") + "A~:~findorder~:~" + order_reference + "~||~");

99.content:
// Builds the manual-registration card for the no-order-reference (orphan) case.
// Christina (ETG): there is no order to register an errand against, so the
// automatic Edvin call is replaced by a screen telling the agent to register it
// by hand, showing exactly the fields Edvin will ask for.
// Her list, verbatim: "We need channel category type and action. And the notes.
// And genesis interaction ID." Genesys interaction TYPE is intentionally absent -
// "it's not mandatory because it's the channel".
//
// One card per errand: node 27 groups on (type + customer_action), so an orphan
// contact can still produce more than one errand to register.

function esc(s) {
  if (s === null || s === undefined) return "";
  return String(s)
    .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}

function row(label, value) {
  const v = (value === null || value === undefined || value === "") ? "-" : value;
  return '<div style="margin:5px 0;font-size:13px;">' +
    '<span style="color:#6b7280;font-weight:600;">' + esc(label) + ':</span> ' +
    '<span style="color:#111827;">' + esc(v) + '</span></div>';
}

const errands = transforms.final_pnrs || [];
const genesysConversationId = ZT.getVariableValue("genesys_conversation_id", "");
const channel = ZT.getVariableValue("zendeskChannelIdentifier", "");
const zdTicketId = ZT.getVariableValue("zd_ticket_id", "");

let cards = errands.map(function (errand, index) {
  return '<div style="border:1px solid #fed7aa;background:#ffffff;border-radius:8px;' +
    'padding:12px 14px;margin:10px 0;">' +
    '<div style="font-weight:700;font-size:13px;color:#9a3412;margin-bottom:6px;">Errand ' +
    (index + 1) + ' of ' + errands.length + '</div>' +
    row("Channel", errand.channel || channel) +
    row("Category", errand.category) +
    row("Type", errand.type) +
    row("Action", errand.customer_action) +
    row("Notes", errand.notes) +
    row("Genesys Interaction ID", genesysConversationId) +
    row("Zendesk Ticket", zdTicketId) +
    '</div>';
}).join("");

if (!errands.length) {
  cards = '<div style="font-size:13px;color:#6b7280;font-style:italic;">' +
    'No errand details were captured for this session.</div>';
}

const html = '<div style="font-family:Arial,Helvetica,sans-serif;max-width:520px;">' +
  '<div style="font-size:13px;color:#7c2d12;line-height:1.5;margin-bottom:4px;">' +
  'This contact has <strong>no order reference</strong>, so Edvin has nothing to register the ' +
  'errand against automatically. Register it manually in Edvin using the details below, then continue the flow until you end the session.';

ZT.setTransformData("manual_errand_registration_html", html);
ZT.setFormData("manual_errand_count", errands.length);
